package com.example.campsitelottery

import androidx.compose.ui.test.assertIsEnabled
import androidx.compose.ui.test.assertIsNotEnabled
import androidx.compose.ui.test.assertTextEquals
import androidx.compose.ui.test.junit4.createComposeRule
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.test.performClick
import androidx.test.ext.junit.runners.AndroidJUnit4
import org.junit.Assert.assertEquals
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith

/**
 * Documentation generated by Claude
 * UI tests for [RateCampsiteDialog].
 */
@RunWith(AndroidJUnit4::class)
class RateCampsiteDialogTest {

    @get:Rule
    val composeRule = createComposeRule()

    @Test
    fun submitIsDisabledUntilAStarIsChosen() {
        composeRule.setContent { RateCampsiteDialog(initialStars = null, onSubmit = {}, onDismiss = {}) }
        composeRule.onNodeWithTag("submitRatingButton").assertIsNotEnabled()
        composeRule.onNodeWithTag("star_3").performClick()
        composeRule.onNodeWithTag("submitRatingButton").assertIsEnabled()
    }

    @Test
    fun submitSendsTheChosenStars() {
        var submitted: Int? = null
        composeRule.setContent { RateCampsiteDialog(initialStars = null, onSubmit = { submitted = it }, onDismiss = {}) }
        composeRule.onNodeWithTag("star_4").performClick()
        composeRule.onNodeWithTag("submitRatingButton").performClick()
        assertEquals(4, submitted)
    }

    @Test
    fun existingRatingIsPrefilled() {
        composeRule.setContent { RateCampsiteDialog(initialStars = 2, onSubmit = {}, onDismiss = {}) }
        composeRule.onNodeWithTag("selectedStarsText").assertTextEquals("2 of 5 stars")
        composeRule.onNodeWithTag("submitRatingButton").assertIsEnabled()
    }
}
